--
-- Table structure for table `promotion_rules`
--

DROP TABLE IF EXISTS `promotion_rules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `promotion_rules` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rule_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_value` decimal(12,2) NOT NULL DEFAULT '0.00',
  `min_order_amount` decimal(12,2) DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `days_of_week` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority` int NOT NULL DEFAULT '50',
  `config` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `starts_at` datetime DEFAULT NULL,
  `ends_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_promotion_rules_code` (`code`),
  KEY `idx_promotion_rules_active` (`is_active`),
  CONSTRAINT `chk_promotion_rules_discount_type` CHECK ((`discount_type` in (_utf8mb4'percent',_utf8mb4'fixed',_utf8mb4'special_price',_utf8mb4'buy_x_get_y'))),
  CONSTRAINT `chk_promotion_rules_discount_value` CHECK ((`discount_value` >= 0)),
  CONSTRAINT `chk_promotion_rules_min_order_amount` CHECK (((`min_order_amount` is null) or (`min_order_amount` >= 0))),
  CONSTRAINT `chk_promotion_rules_type` CHECK ((`rule_type` in (_utf8mb4'combo_fixed',_utf8mb4'time_window',_utf8mb4'invoice_threshold',_utf8mb4'code',_utf8mb4'bundle_special_price',_utf8mb4'day_of_week')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
